package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.Date;import java.sql.SQLException;import java.util.*;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.*;
@WebServlet("/admin/atividades") public class AtividadeServlet extends HttpServlet{
 private static final Set<String> TIPOS=Set.of("projeto","estagio","tarefa","oficina","palestra","evento","competicao","visita");private static final Set<String> STATUS=Set.of("planejada","em_andamento","concluida");private final AtividadeDAO dao=new AtividadeDAO();private final CoordenadorDAO coordenadorDAO=new CoordenadorDAO();private final PeriodoLetivoDAO periodoDAO=new PeriodoLetivoDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("atividades",dao.listar());r.setAttribute("coordenadores",coordenadorDAO.listarAtivos());r.setAttribute("todosCoordenadores",coordenadorDAO.listar());r.setAttribute("periodos",periodoDAO.listar());r.getRequestDispatcher("/WEB-INF/views/admin/atividades.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String acao=r.getParameter("acao");try{if("excluir".equals(acao)){dao.excluir(id(r,"id"));redir(r,p,"exclusao");return;}Atividade a=new Atividade();if("editar".equals(acao))a.setId(id(r,"id"));a.setTitulo(obrigatorio(r,"titulo"));a.setTipo(obrigatorio(r,"tipo"));a.setDescricao(obrigatorio(r,"descricao"));a.setStatus(obrigatorio(r,"status"));a.setCoordenadorId(id(r,"coordenadorId"));if(!TIPOS.contains(a.getTipo()))throw new IllegalArgumentException("erro.atividade.tipoInvalido");if(!STATUS.contains(a.getStatus()))throw new IllegalArgumentException("erro.atividade.statusInvalido");a.setDataInicio(Date.valueOf(obrigatorio(r,"dataInicio")));String fim=r.getParameter("dataFim");if(fim!=null&&!fim.isBlank())a.setDataFim(Date.valueOf(fim));if(a.getDataFim()!=null&&a.getDataFim().before(a.getDataInicio()))throw new IllegalArgumentException("erro.atividade.dataInvalida");List<Long> periodos=periodos(r);if(periodos.isEmpty())throw new IllegalArgumentException("erro.periodo.obrigatorio");if("editar".equals(acao))dao.atualizarComPeriodos(a,periodos);else dao.inserirComPeriodos(a,periodos);redir(r,p,"editar".equals(acao)?"alteracao":"cadastro");}catch(IllegalArgumentException e){r.setAttribute("erro",e.getMessage());doGet(r,p);}catch(SQLException e){throw new ServletException("Erro ao processar atividade.",e);}}
 private List<Long> periodos(HttpServletRequest r){LinkedHashSet<Long>s=new LinkedHashSet<>();String[]v=r.getParameterValues("periodoId");if(v!=null)for(String x:v)if(x!=null&&!x.isBlank())s.add(Long.valueOf(x));return new ArrayList<>(s);}private Long id(HttpServletRequest r,String n){return Long.valueOf(r.getParameter(n));}private String obrigatorio(HttpServletRequest r,String n){String v=r.getParameter(n);if(v==null||v.isBlank())throw new IllegalArgumentException("erro.campo.obrigatorio");return v.trim();}private void redir(HttpServletRequest r,HttpServletResponse p,String s)throws IOException{p.sendRedirect(r.getContextPath()+"/admin/atividades?sucesso="+s);}}
